def choose_move(observation):
    w = observation.get("grid_width", 8)
    h = observation.get("grid_height", 8)
    try:
        w = int(w or 8)
    except:
        w = 8
    try:
        h = int(h or 8)
    except:
        h = 8

    sp = observation.get("self_position", (0, 0)) or (0, 0)
    op = observation.get("opponent_position", (0, 0)) or (0, 0)
    sx, sy = int(sp[0]), int(sp[1])
    ox, oy = int(op[0]), int(op[1])

    blocked = set()
    for p in observation.get("obstacles", []) or []:
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            x, y = int(p[0]), int(p[1])
            if 0 <= x < w and 0 <= y < h:
                blocked.add((x, y))

    def cheb(ax, ay, bx, by):
        dx = ax - bx
        if dx < 0:
            dx = -dx
        dy = ay - by
        if dy < 0:
            dy = -dy
        return dx if dx > dy else dy

    resources = []
    for p in observation.get("resources", []) or []:
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            x, y = int(p[0]), int(p[1])
            if 0 <= x < w and 0 <= y < h and (x, y) not in blocked:
                resources.append((x, y))

    if not resources:
        candidates = [(-1, 0), (1, 0), (0, -1), (0, 1), (0, 0)]
        for dx, dy in candidates:
            nx, ny = sx + dx, sy + dy
            if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in blocked:
                return [dx, dy]
        return [0, 0]

    best = None
    best_key = None
    for x, y in resources:
        my_d = cheb(sx, sy, x, y)
        opp_d = cheb(ox, oy, x, y)
        key = (my_d - opp_d, my_d, x, y)
        if best_key is None or key < best_key:
            best_key = key
            best = (x, y)

    tx, ty = best
    dx_t = tx - sx
    dy_t = ty - sy
    sdx = 0 if dx_t == 0 else (1 if dx_t > 0 else -1)
    sdy = 0 if dy_t == 0 else (1 if dy_t > 0 else -1)

    dirs = [(sdx, 0), (0, sdy), (sdx, sdy), (sdx, -sdy), (-sdx, sdy), (-sdx, -sdy), (0, 0)]
    best_move = None
    best_move_key = None
    for dx, dy in dirs:
        nx, ny = sx + dx, sy + dy
        if not (0 <= nx < w and 0 <= ny < h) or (nx, ny) in blocked:
            continue
        d_next = cheb(nx, ny, tx, ty)
        d_opp_next = cheb(ox, oy, tx, ty)
        key = (d_next - d_opp_next, d_next, dx, dy)
        if best_move_key is None or key < best_move_key:
            best_move_key = key
            best_move = (dx, dy)

    if best_move is None:
        return [0, 0]
    return [int(best_move[0]), int(best_move[1])]

